HTML = r'''
<div id="trend-overview"><div class="overview-intro"><h2 id="overview-title" class="overview-plain-title" tabindex="-1">产品排名与评分简报</h2><p>先看统计范围和变化，再选产品对比；点击产品名可查逐日数据。</p></div>
<details class="overview-filter-box" id="overview-filters" open><summary class="overview-filter-toggle">更改统计范围 · 平台、市场、榜单和日期</summary><div class="toolbar overview-toolbar"><label>平台<select id="overview-platform"><option value="ios">iOS</option><option value="android">Android</option></select></label><label>市场<select id="overview-country"></select></label><label>榜单<select id="overview-chart"><option value="free">免费榜</option><option value="paid">付费榜</option></select></label><label>查看多久<select id="overview-window"><option value="7" selected>近7天</option><option value="30">近30天</option></select></label><button type="button" id="overview-reset" class="brief-action">恢复默认范围</button></div><details id="overview-more-filters" class="overview-more-filters"><summary>更多筛选 · 选择产品范围、榜单状态和数量</summary><div class="toolbar"><label>统计哪些产品<select id="overview-pool"><option value="today">只看报告当日在榜的产品</option><option value="period" selected>这段时间上过榜的产品（含已离榜）</option></select></label><label>报告日榜单状态<select id="overview-status"><option value="all">全部状态</option><option value="ranked">当前在榜</option><option value="off_chart">已确认离榜</option><option value="unknown">状态未知</option></select></label><label>统计多少款<select id="overview-limit"><option value="10">前10款</option><option value="20">前20款</option><option value="50">前50款</option><option value="100">前100款</option><option value="all" selected>全部产品</option></select></label></div><p>默认把所选日期内曾经上榜的产品都纳入，包括已经离榜的产品。若限制数量，按所选范围的排序取前N款。</p></details></details>
<details class="overview-method"><summary>统计范围与采集说明</summary><div class="overview-help" id="overview-how"></div><p class="overview-scope" id="overview-scope"></p></details>__BRIEFING____COMPARISON__<details class="overview-detail-panel" id="overview-details"><summary>展开数据明细 · 变化列表与逐日对照表</summary>__STATISTICS_LIST__<div class="tablewrap overview-matrix" id="overview-scroll" hidden tabindex="0" aria-label="产品与日期对照表，可横向滚动"><table><thead id="overview-head"></thead><tbody id="overview-rows"></tbody></table><div class="empty" id="overview-empty" hidden></div></div><p id="overview-count" class="overview-caption" aria-live="polite"></p><p class="overview-caption">左右滑动查看日期，产品名固定；超过20款时可在表内上下滚动查看更多。点击产品名称打开单个 App 的图表与明细。</p><p class="overview-caption" id="overview-legend"></p></details></div>
'''

JS = r'''
const overviewMetrics={rank:'逐日排名（名）',daily:'每日新增评分（条）',total:'累计评分（条）'};
function overviewCountries(){const old=el('overview-country').value||'cn',countries=el('overview-platform').value==='ios'?['cn','us','jp','gb']:['us','jp','gb'];el('overview-country').replaceChildren();for(const c of countries){const opt=node('option',names[c]);opt.value=c;el('overview-country').append(opt);}el('overview-country').value=countries.includes(old)?old:'us';}
function overviewCell(r,kind,metric){if(!r)return {text:'未观测',reason:'该日期没有可用观测',value:null};if(metric==='rank'){const v=r[kind+'_rank'];return numberValue(v)?{text:'#'+v,reason:'该日榜单第'+v+'名',value:v}:{text:({off_chart:'未入前100',not_returned:'短榜未返',missing:'未观测'}[r[kind+'_status']]||'未观测'),reason:rankState(r,kind),value:null};}const field=metric==='daily'?'rating_delta_1d':'rating_count',v=r[field];return numberValue(v)?{text:fmt(v),reason:metric==='daily'?'当天新增'+fmt(v)+'条评分':'累计'+fmt(v)+'条评分',value:v}:{text:metric==='total'?'评分缺失':({current_missing:'当日缺失',previous_missing:'前日缺失',count_decreased:'数值回退'}[r.rating_delta_status]||'不可计算'),reason:metric==='daily'?ratingReason(r):'该日累计评分缺失',value:null};}
function overviewNameCell(p,stats){const cell=node('td'),button=node('button',p.name,'overview-open');button.type='button';button.title='查看'+p.name+'的单产品详情';button.addEventListener('click',()=>openProductTrend(p,el('overview-window').value));cell.append(button,node('div',stats.ranked?'本期最好 #'+stats.best+' · 最近上榜 '+stats.last.slice(5):'本窗口没有上榜记录','overview-row-caption'));return cell;}
function overviewChangeCell(values,dates,metric){const cell=node('td');if(metric==='daily'){const valid=values.filter(v=>v.value!==null);cell.append(node('strong',valid.length?fmt(valid.reduce((n,v)=>n+v.value,0))+'条':'无可比值'),node('div',valid.length+'/'+dates.length+'天可计算','sub'));}else{const a=values[0]?.value,b=values[values.length-1]?.value;if(a!==null&&a!==undefined&&b!==null&&b!==undefined){const delta=metric==='rank'?a-b:b-a;cell.append(node('strong',metric==='rank'?(delta>0?'↑'+delta+'名':delta<0?'↓'+(-delta)+'名':'持平'):(delta>=0?'增加'+fmt(delta)+'条':'回退'+fmt(-delta)+'条')),node('div',dates[0].slice(5)+' → '+dates[dates.length-1].slice(5),'sub'));}else cell.append(node('span','起止日不可比','sub'));}return cell;}
function renderOverviewView(){const changes=el('overview-view').value==='changes';el('overview-changes-scroll').hidden=!changes;el('overview-scroll').hidden=changes;el('overview-metric').disabled=changes;}
function renderOverview(){
 const platform=el('overview-platform').value,country=el('overview-country').value,kind=el('overview-chart').value,pool=el('overview-pool').value,chart=(platform==='android'?'android-':'')+'top-'+kind,metric=el('overview-metric').value,rawLimit=el('overview-limit').value,limit=rawLimit==='all'?Infinity:Number(rawLimit),limitLabel=rawLimit==='all'?'全部产品':'前'+limit+'款',days=Number(el('overview-window').value),first=new Date(data.as_of+'T00:00:00Z');first.setUTCDate(first.getUTCDate()-days+1);
 const dates=(trendData.dates||[]).filter(d=>d>=first.toISOString().slice(0,10)),source=(collection.chart_status||[]).find(c=>c.country===country&&c.chart===chart&&(!c.date||c.date===data.as_of));
 const candidates=trendSeries.filter(p=>p.platform===platform&&p.country===country).map(p=>({p,stats:holdingStats(p,kind,dates),today:p.observations.find(r=>r.date===data.as_of)}));
 const poolMembers=pool==='today'?(source?.status==='ok'?candidates.filter(v=>numberValue(v.today?.[kind+'_rank'])).sort((a,b)=>a.today[kind+'_rank']-b.today[kind+'_rank']):[]):candidates.filter(v=>v.stats.ranked>0).sort((a,b)=>a.stats.best-b.stats.best||b.stats.last.localeCompare(a.stats.last)||a.p.app_id.localeCompare(b.p.app_id));
 if(pool==='today')el('overview-status').value='all';el('overview-status').disabled=pool==='today';const statusFilter=el('overview-status').value;const members=poolMembers.filter(v=>statusFilter==='all'||(statusFilter==='ranked'&&numberValue(v.today?.[kind+'_rank']))||(statusFilter==='off_chart'&&v.today?.[kind+'_status']==='off_chart')||(statusFilter==='unknown'&&!numberValue(v.today?.[kind+'_rank'])&&v.today?.[kind+'_status']!=='off_chart'));
 const selected=members.slice(0,limit),cohort=selected.map(v=>v.p),label=(platform==='ios'?'iOS':'Android')+' · '+names[country]+' · '+(kind==='free'?'免费榜':'付费榜'),poolLabel=pool==='today'?'报告当日在榜':'期间曾上过榜';
 el('overview-how').textContent='当前观察池：'+poolLabel+' · '+label+'。'+(pool==='today'?'按'+data.as_of+'榜单名次排列，显示'+limitLabel+'。':'收录所选日期内至少一次真实上榜的产品，包括报告当日已离榜者；按期间最好名次排列，显示'+limitLabel+'，可选全部查看完整名单。')+'名单固定后回看逐日变化。';
 const chartRows=(trendData.chart_status||collection.chart_status||[]).filter(c=>c.country===country&&c.chart===chart&&dates.includes(c.date)),success=chartRows.filter(c=>c.status==='ok'),complete=success.filter(c=>c.count>=(data.coverage?.chart_limit||100)),globalCount=data.summary?.product_market_count??products.length;
 el('overview-scope').textContent='本日报：'+(collection.chart_status||[]).filter(c=>c.status==='ok').length+'张有效榜单、'+fmt(globalCount)+'条当日产品市场观测（含离榜跟踪）。当前观察池共'+poolMembers.length+'款，状态筛选后'+members.length+'款，展示'+cohort.length+'款；'+(source?.status==='ok'?'报告当日榜单实际返回'+source.count+'款。':'报告当日该榜单没有有效观测。')+'所选日期榜单成功观测'+success.length+'/'+dates.length+'天，其中完整榜'+complete.length+'天、短榜'+(success.length-complete.length)+'天；短榜未返回不视为离榜。';
 el('overview-legend').textContent=metric==='rank'?'未入前100：完整前100榜单中没有该App；短榜未返：来源不足100条且未返回该App；未观测：该日榜单数据缺失。均不补成0或第100名。':metric==='daily'?'当日缺失、前日缺失或累计数回退时不计算新增；0条是有效观测。合计仅加总有值日期。':'评分缺失表示没有取得该日累计评分，不用旧值填充；起止日变化是累计数之差，不是下载量。';
 const weekStart=new Date(data.as_of+'T00:00:00Z');weekStart.setUTCDate(weekStart.getUTCDate()-6);
 el('overview-stat-note').textContent='持榜天数按上方实际展示日期统计；明确上榜或完整榜未出现时才可判定，短榜未返和请求缺失记为未知。小折线统一第1—100名，缺失断线。7日新增评分固定统计'+weekStart.toISOString().slice(0,10)+'至'+data.as_of+'，只合计有效日期，旁边标明有效几天/7天。';
 const changes=el('overview-view').value==='changes';el('overview-table-title').textContent=(changes?'变化列表 · 排名、持榜与7日评分':overviewMetrics[metric])+' · '+poolLabel+(statusFilter==='all'?'':' / '+({ranked:'当前在榜',off_chart:'已确认离榜',unknown:'状态未知'}[statusFilter]))+' · '+(dates.length?dates[0]+' 至 '+dates[dates.length-1]+'（'+dates.length+'天）':'尚无日期记录');
 renderBriefing(cohort,dates,{kind,label,poolLabel,statusLabel:({all:'全部报告日状态',ranked:'当前在榜',off_chart:'已确认离榜',unknown:'状态未知'}[statusFilter]),poolCount:poolMembers.length,filteredCount:members.length,pool,sourceDays:success.length,fullChartDays:complete.length});
 updateRankComparison(cohort,dates,{platform,country,kind,label,pool,poolLabel:poolLabel+(statusFilter==='all'?'':' · '+({ranked:'当前在榜',off_chart:'已确认离榜',unknown:'状态未知'}[statusFilter])),limitLabel,statusFilter});for(const id of ['overview-scroll','overview-changes-scroll'])el(id).classList.toggle('overview-short-list',cohort.length<=20);
 el('overview-head').replaceChildren();el('overview-rows').replaceChildren();el('overview-changes').replaceChildren();const header=node('tr');header.append(node('th','产品'));for(const day of dates){const th=node('th',null,day===data.as_of?'overview-latest':'');th.scope='col';th.append(node('span',day.slice(5),'overview-date'));if(day===data.as_of)th.append(node('span','报告当日','sub'));header.append(th);}for(const title of [metric==='daily'?'有效日新增合计':'起止日变化','持榜天数 · 所选日期','近7日新增评分 · 有效日合计']){const th=node('th',title);th.scope='col';header.append(th);}el('overview-head').append(header);
 for(const {p,stats,today}of selected){const tr=node('tr');tr.dataset.appId=p.app_id;tr.append(overviewNameCell(p,stats));const values=[];for(const day of dates){const r=p.observations.find(r=>r.date===day),value=overviewCell(r,kind,metric),td=node('td',value.text,(value.value===null?'overview-null':'overview-value')+(day===data.as_of?' overview-latest':''));td.dataset.date=day;td.dataset.value=value.value===null?'':String(value.value);td.title=day+' · '+p.name+' · '+value.reason;values.push(value);tr.append(td);}tr.append(overviewChangeCell(values,dates,metric));appendHoldingCell(tr,stats);appendRatingWeekCell(tr,p);el('overview-rows').append(tr);
 const changeRow=node('tr');changeRow.dataset.appId=p.app_id;changeRow.append(overviewNameCell(p,stats));const current=overviewCell(today,kind,'rank'),rankCell=node('td',current.text,current.value===null?'overview-null':'overview-value');rankCell.title=current.reason;changeRow.append(rankCell,overviewChangeCell(dates.map(day=>overviewCell(p.observations.find(r=>r.date===day),kind,'rank')),dates,'rank'));const sparkCell=node('td');sparkCell.append(rankSparkline(p,kind,dates));changeRow.append(sparkCell);appendHoldingCell(changeRow,stats);appendRatingWeekCell(changeRow,p);el('overview-changes').append(changeRow);}
 const empty=pool==='today'&&source?.status!=='ok'?'报告当日该榜单没有有效观测，不用旧榜单冒充当日榜单。':'所选观察池没有可展示的产品。';for(const id of ['overview-empty','overview-changes-empty']){el(id).hidden=cohort.length>0;el(id).textContent=empty;}
 if(!cohort.length)el('overview-filters').open=true;el('overview-count').textContent=poolLabel+'：共'+poolMembers.length+'款，状态筛选后'+members.length+'款，展示'+cohort.length+'款 × '+dates.length+'个日期。'+(pool==='period'?'按期间最好名次排序；包含已离榜产品，不只看今天的前N名。':'按报告当日名次固定名单回看历史。')+' 持榜和7日评分均标注有效天数，不作机会或商业判断。';renderOverviewView();
}
function showTrendDetail(){document.body.classList.remove('trend-overview-active');el('trend-overview').hidden=true;el('trend-detail').hidden=false;}
function showTrendOverview(){el('trend-detail').hidden=true;el('trend-overview').hidden=false;document.body.classList.add('trend-overview-active');renderOverview();el('overview-title').focus();}
el('overview-reset').addEventListener('click',()=>{el('overview-platform').value='ios';overviewCountries();el('overview-country').value='cn';el('overview-chart').value='free';el('overview-window').value='7';el('overview-pool').value='period';el('overview-status').value='all';el('overview-limit').value='all';el('brief-rating-coverage').value='complete';el('brief-movement-direction').value='all';el('overview-more-filters').open=false;renderOverview();});
el('overview-platform').addEventListener('change',()=>{overviewCountries();renderOverview();});for(const id of ['overview-country','overview-chart','overview-pool','overview-status','overview-limit','overview-metric','overview-window','overview-view'])el(id).addEventListener('change',renderOverview);el('overview-back').addEventListener('click',showTrendOverview);overviewCountries();renderOverview();
const overviewCompact=window.matchMedia?.('(max-width:600px)');if(overviewCompact){el('overview-filters').open=!overviewCompact.matches||!(briefingContext?.cohort.length);overviewCompact.addEventListener?.('change',e=>{el('overview-filters').open=!e.matches||!(briefingContext?.cohort.length);});}
'''
